ch-input {max-width:none;width:100%;}.filter-buttons {gap:0;}.filter-buttons>.g-button {font-size:var(--g-text-caption-2-font-size);}.notes-grid {grid-template-columns:1fr;}.note-card {min-height:290px;}.dialog-content {padding:var(--g-spacing-5);}.dialog-actions {flex-wrap:wrap;}.project-detail .dialog-actions>.g-button {font-size:var(--g-text-body-1-font-size);}}
