item.command:
/bin/bash -lc "cat > src/styles.css <<'EOF'
.g-root_theme_light,
.g-root_theme_dark {
  --g-color-base-brand: var(--g-color-base-utility-heavy);
  --g-color-base-brand-hover: var(--g-color-base-utility-heavy-hover);
  --g-color-base-selection: var(--g-color-base-utility-light);
  --g-color-base-selection-hover: var(--g-color-base-utility-light-hover);
  --g-color-line-brand: var(--g-color-base-utility-heavy);
  --g-color-line-focus: var(--g-color-base-utility-heavy);
  --g-color-text-brand: var(--g-color-text-utility);
  --g-color-text-brand-heavy: var(--g-color-text-utility-heavy);
  --g-color-text-brand-contrast: var(--g-color-text-light-primary);
  --g-color-text-link: var(--g-color-text-utility);
  --g-color-text-link-hover: var(--g-color-text-utility-heavy);
  --g-button-border-radius: var(--g-border-radius-m);
  --g-card-border-radius: var(--g-border-radius-xl);
  --page-surface: color-mix(in srgb, var(--g-color-base-generic) 35%, var(--g-color-base-background));
}
* {box-sizing: border-box;}
body {margin:0; min-width:360px; -webkit-font-smoothing:antialiased;}
a {color:inherit;}
button, a, label { -webkit-tap-highlight-color:transparent; }
::selection {background:var(--g-color-base-selection);}
.app-shell {
  --gn-aside-header-background-color: var(--g-color-base-background);
  --gn-aside-header-expanded-background-color: var(--g-color-base-background);
  --gn-aside-header-collapsed-background-color: var(--g-color-base-background);
  --gn-aside-header-item-current-background-color: var(--g-color-base-utility-light);
  --gn-aside-header-item-current-background-color-hover: var(--g-color-base-utility-light-hover);
  --gn-aside-header-item-current-icon-color: var(--g-color-text-utility);
  --gn-aside-header-item-current-text-color: var(--g-color-text-utility-heavy);
  --gn-aside-header-item-expanded-radius: var(--g-border-radius-m);
  --gn-aside-header-item-text-color: var(--g-color-text-secondary);
  --gn-aside-header-item-icon-color: var(--g-color-text-secondary);
  --gn-aside-header-divider-vertical-color: var(--g-color-line-generic);
  --gn-aside-header-padding-top: var(--g-spacing-5);
  --gn-aside-header-item-icon-background-color: transparent;
}
.brand-logo {color:var(--g-color-text-utility);}
.sidebar-intro {padding:var(--g-spacing-6) var(--g-spacing-5) var(--g-spacing-3);letter-spacing:1.3px;}
.favorites-label {padding:var(--g-spacing-8) var(--g-spacing-3) var(--g-spacing-2);font-size:var(--g-text-caption-2-font-size);letter-spacing:1.3px;color:var(--g-color-text-hint);}
.nav-count,.section-count {display:inline-flex;align-items:center;justify-content:center;min-width:23px;height:23px;border-radius:var(--g-border-radius-s);background:var(--g-color-base-generic);font-size:var(--g-text-caption-2-font-size);color:var(--g-color-text-secondary);}
.favorite-dot {display:inline-block;width:7px;height:7px;border-radius:50%;flex-shrink:0;background:var(--g-color-text-utility);}
.favorite-dot.green {background:var(--g-color-text-positive);}
.favorite-dot.orange {background:var(--g-color-text-warning);}
.sidebar-footer {padding:var(--g-spacing-4) var(--g-spacing-4) var(--g-spacing-2);}
.sidebar-tip {background:var(--page-surface);border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);padding:var(--g-spacing-4);margin-bottom:var(--g-spacing-6);display:flex;flex-direction:column;gap:var(--g-spacing-3);}
.sidebar-tip .g-button {align-self:flex-start;margin-left:calc(-1 * var(--g-spacing-2));color:var(--g-color-text-utility);}
.tip-icon {color:var(--g-color-text-utility);}
.sidebar-tip> .g-text {line-height:1.6;}
.theme-row {padding:var(--g-spacing-2) var(--g-spacing-1) var(--g-spacing-5);color:var(--g-color-text-secondary);}
.flexible {flex:1;min-width:0;}
.profile-button {height:auto;min-height:64px;border-top:1px solid var(--g-color-line-generic);border-radius:0;text-align:left;padding:var(--g-spacing-3) 0;}
.profile-copy {display:flex;flex-direction:column;gap:var(--g-spacing-1);}
.profile-avatar {flex-shrink:0;--g-avatar-background-color:var(--g-color-base-utility-light);color:var(--g-color-text-utility);}
.is-compact {padding:var(--g-spacing-2);}
.is-compact .theme-row {justify-content:center;position:relative;padding:var(--g-spacing-2) 0 var(--g-spacing-4);}
.is-compact .theme-row>.g-icon {display:none;}
.is-compact .profile-button {padding:var(--g-spacing-3) 0;}
.content-shell {height:100vh;overflow-y:auto;min-width:0;background:var(--page-surface);}
.topbar {height:76px;padding:0 var(--g-spacing-8);background:var(--g-color-base-background);border-bottom:1px solid var(--g-color-line-generic);display:flex;align-items:center;justify-content:space-between;gap:var(--g-spacing-3);}
.breadcrumb-muted,.top-date {color:var(--g-color-text-secondary);font-size:var(--g-text-body-1-font-size);}
.breadcrumb-divider {color:var(--g-color-text-hint);padding:0 var(--g-spacing-2);}
.top-date {display:flex;align-items:center;gap:var(--g-spacing-2);text-transform:capitalize;}
.topbar-divider {height:22px;width:1px;background:var(--g-color-line-generic);}
.notification-icon {display:inline-flex;position:relative;}
.notification-icon i {position:absolute;top:0;right:0;width:5px;height:5px;border-radius:50%;background:var(--g-color-base-brand);outline:2px solid var(--g-color-base-background);}
.main-content {max-width:1520px;margin:auto;padding:var(--g-spacing-8);}
.page-heading {margin:var(--g-spacing-2) 0 var(--g-spacing-7);}
.page-heading h1 {margin:0;font-weight:600;letter-spacing:-.8px;}
.page-heading p {margin:var(--g-spacing-3) 0 0;}
.greeting-spark {font-size:32px;color:var(--g-color-text-utility);line-height:1;}
.primary-create {flex-shrink:0;--g-button-background-color:var(--g-color-base-brand);}
.welcome-banner {position:relative;overflow:hidden;display:flex;min-height:264px;border:1px solid color-mix(in srgb,var(--g-color-base-utility-heavy) 12%,transparent);border-radius:var(--g-border-radius-xl);background:linear-gradient(110deg,var(--g-color-base-utility-light),color-mix(in srgb,var(--g-color-base-utility-medium) 65%,var(--g-color-base-background)));}
.welcome-copy {position:relative;z-index:2;padding:var(--g-spacing-8) var(--g-spacing-9);width:64%;}
.eyebrow {display:flex;align-items:center;gap:var(--g-spacing-2);font-size:10px;font-weight:600;letter-spacing:1.6px;color:var(--g-color-text-utility-heavy);}
.live-dot {width:6px;height:6px;border-radius:50%;background:var(--g-color-text-utility);}
.welcome-copy h2 {margin:var(--g-spacing-4) 0 var(--g-spacing-3);line-height:1.14;letter-spacing:-1.2px;font-weight:550;}
.welcome-copy p {margin:0 0 var(--g-spacing-5);color:var(--g-color-text-secondary);line-height:1.65;}
.welcome-copy .g-button {--g-button-background-color:var(--g-color-base-background);--g-button-background-color-hover:var(--g-color-base-float-hover);--g-button-border-color:var(--g-color-line-generic);}
.hero-visual {width:43%;position:absolute;right:0;top:0;height:100%;color:var(--g-color-base-utility-heavy);}
.hero-orbit {position:absolute;width:300px;height:140px;left:50%;top:50%;border:1px solid color-mix(in srgb,var(--g-color-text-utility) 28%,transparent);border-radius:50%;transform:translate(-50%,-50%) rotate(-40deg);}
.orbit-b {width:340px;height:175px;transform:translate(-50%,-50%) rotate(-40deg);}
.orbit-c {width:380px;height:210px;transform:translate(-50%,-50%) rotate(-40deg);}
.hero-planet {position:absolute;width:137px;height:137px;left:50%;top:50%;transform:translate(-50%,-50%) rotate(-15deg);border-radius:32%;background:linear-gradient(145deg,var(--g-color-base-background),var(--g-color-base-utility-medium));box-shadow:13px 20px 35px var(--g-color-base-utility-light);display:flex;justify-content:center;align-items:center;border:1px solid var(--g-color-base-background);}
.hero-planet svg {width:80px;height:80px;filter:drop-shadow(2px 4px 0 var(--g-color-base-utility-medium));color:var(--g-color-text-utility);}
.hero-star {position:absolute;left:13%;top:17%;font-size:35px;color:var(--g-color-text-utility);}
.hero-star.small {left:82%;top:65%;font-size:23px;}
.hero-small-planet {position:absolute;width:20px;height:20px;border-radius:50%;background:linear-gradient(145deg,var(--g-color-base-background),var(--g-color-base-utility-heavy));left:77%;top:17%;}
.floating-label {position:absolute;display:flex;align-items:center;gap:var(--g-spacing-2);padding:var(--g-spacing-3) var(--g-spacing-4);background:var(--g-color-base-background);border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-m);color:var(--g-color-text-secondary);font-size:var(--g-text-body-1-font-size);box-shadow:0 6px 22px var(--g-color-base-utility-light);white-space:nowrap;}
.floating-label .g-icon {color:var(--g-color-text-utility);}
.label-idea {right:9%;top:22%;transform:rotate(7deg);}
.label-done {left:8%;bottom:17%;transform:rotate(-7deg);}
.label-done .g-icon {color:var(--g-color-text-positive);}
.stats-grid {display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--g-spacing-4);margin:var(--g-spacing-5) 0 var(--g-spacing-8);}
.stat-card {padding:var(--g-spacing-4) var(--g-spacing-5);background:var(--g-color-base-background);display:flex;flex-direction:column;gap:var(--g-spacing-2);}
.stat-icon {height:30px;width:30px;display:flex;align-items:center;justify-content:center;flex-shrink:0;border-radius:var(--g-border-radius-m);}
.purple {--art-bg:var(--g-color-base-utility-light);--art-fill:var(--g-color-base-utility-heavy);--art-medium:var(--g-color-base-utility-medium);--art-text:var(--g-color-text-utility);}
.green {--art-bg:var(--g-color-base-positive-light);--art-fill:var(--g-color-base-positive-heavy);--art-medium:var(--g-color-base-positive-medium);--art-text:var(--g-color-text-positive);}
.orange {--art-bg:var(--g-color-base-warning-light);--art-fill:var(--g-color-text-warning-heavy);--art-medium:var(--g-color-base-warning-medium);--art-text:var(--g-color-text-warning-heavy);}
.blue {--art-bg:var(--g-color-base-info-light);--art-text:var(--g-color-text-info);}
.stat-icon {background:var(--art-bg);color:var(--art-text);}
.stat-number {font-weight:550;letter-spacing:-1.5px;}
.section-heading {margin-bottom:var(--g-spacing-4);min-height:32px;gap:var(--g-spacing-2);}
.section-heading h2 {margin:0;font-weight:550;letter-spacing:-.5px;}
.section-heading>.g-button {color:var(--g-color-text-secondary);}
.projects-grid {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--g-spacing-5);}
.project-card {overflow:hidden;background:var(--g-color-base-background);transition:box-shadow .2s,transform .2s;}
