const {App}=await import('./node_modules/.cache/orbita-smoke.mjs');
const React=await import('react');
const {renderToString}=await import('react-dom/server');
globalThis.window={innerWidth:1400};
const errors=[];
const originalError=console.error;
console.error=(...args)=>{if("'!String(args[0]).includes('"'useLayoutEffect does nothing on the server'))errors.push(args);};
let checks=0;
for(const theme of ['light','dark']) {
 for(const page of ['overview','projects','notes']) {
  for(const empty of [false,true]) {
   globalThis.location={hash:'#/'+page};
   globalThis.localStorage={getItem:(key)=>key==='orbita-theme'?JSON.stringify(theme):empty&&['orbita-projects','orbita-notes'].includes(key)?'[]':null};
   const html=renderToString(React.createElement(App));
   const expected=page==='overview'?'Всё начинается с идеи':page==='projects'?(empty?'Здесь пока нет проектов':'Новый взгляд на бренд'):(empty?'Здесь пока нет заметок':'Идеи приходят в движении');
   if("'!html.includes(expected))throw Error(`Missing expected content: ${theme}/${page}/${empty}`);
   checks++;
  }
 }
}
console.error=originalError;
if(errors.length){for(const e of errors)console.error(...e);throw Error('"'Unexpected rendering warnings');}
console.log("'`Static rendering passed: ${checks} page/theme/empty-state combinations.`);
